/**
 * Mock review queue for DATA_SOURCE=mock.
 *
 * The cases are generated by the REAL pipeline (pipeline.match + pipeline.proposals.build_cases) on the committed
 * website scrape and pre-change CRM export (`.venv/Scripts/python web/scripts/gen-mock-cases.py`), so mock mode
 * shows exactly what production shows. Here they only get the row fields the review store adds (id, status, run),
 * and the fake CRM is seeded from the same snapshot (lib/mock/snapshot.json, `npm run gen:mock`).
 * Nothing in mock mode touches the network, the real CRM, or the database.
 */
import generated from "./pipeline-cases.json";
import snapshot from "./snapshot.json";
import type { Case, CaseEvent, CrmAccount, CrmContact, MatchResult, Run } from "../types";

export const BELLHAVEN_ID = "0015QAPLGS3FVYEEEM";
const PROPOSED_AT = "2026-11-21T19:40:00.000Z";

const SNAP = snapshot as unknown as { accounts: CrmAccount[]; contacts: CrmContact[] };
const GEN = generated as unknown as { cases: Omit<Case, "id" | "status">[]; match_results: MatchResult[] };

export const snapshotAccounts = () => structuredClone(SNAP.accounts);
export const snapshotContacts = () => structuredClone(SNAP.contacts);

export function buildMockCases(): Case[] {
  return GEN.cases.map((c, i) => ({
    ...structuredClone(c),
    id: i + 1, status: "pending", first_seen_run: 1, last_seen_run: 1,
    decided_at: null, decided_by: null, decided_via: null, decision_note: null,
    final_operations: null, result: null, error: null, created_at: PROPOSED_AT, updated_at: PROPOSED_AT,
  }) as Case);
}

/** The pipeline's own audit entry for each case ("proposed by run #1"), as the real pipeline writes it. */
export function buildMockEvents(cases: Case[]): Omit<CaseEvent, "id">[] {
  return cases.map((c) => ({
    case_id: c.id, at: PROPOSED_AT, event: "proposed", actor: "pipeline run #1", via: "pipeline",
    detail: { run_id: 1, fingerprint: c.fingerprint },
  }));
}

export function buildMockRuns(cases: Case[]): Run[] {
  const results = structuredClone(GEN.match_results);
  return [{
    id: 1, started_at: "2026-11-21T19:38:12.000Z", finished_at: "2026-11-21T19:39:58.000Z", trigger: "manual",
    status: "succeeded", location_count: 35, account_count: 121, error: null, match_results: results,
    summary: {
      new: cases.length, refreshed: 0, skipped_decided: 0, superseded: 0,
      in_sync: results.filter((m) => m.classification === "in_sync").length,
      scrape: { claimed_count: 35, directory_count: 34, found_count: 35, pages_visited: 3, homepage_only: ["bellhaven-meadows-of-findlay"], complete: true },
    },
  }];
}
